import csv, json
from pathlib import Path
from datetime import datetime, timezone

today = datetime.now(timezone.utc).date().isoformat()
R=Path('data/data_resources.csv'); P=Path('data/data_products.csv'); D=Path('data/product_distributions.csv'); B=Path('data/brazil_scope_priorities.json')

def read(path):
    with path.open(encoding='utf-8', newline='') as f:
        r=csv.DictReader(f); return r.fieldnames, list(r)
def append(path, rows):
    fields,_=read(path)
    with path.open('a',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields,lineterminator='\n')
        for row in rows: w.writerow({k:row.get(k,'') for k in fields})

_,rs=read(R); _,ps=read(P); _,ds=read(D)
rids={x['resource_id'] for x in rs}; pids={x['product_id'] for x in ps}; dids={x['distribution_id'] for x in ds}; urls={x['product_page_url'] for x in ps if x.get('product_page_url')}

