if source['resource_id'] not in rids:
    if any(x.get('homepage_url')==source['homepage_url'] for x in rs): raise SystemExit('INMET already cataloged under another resource')
    append(R,[source])
add=[]
for p in products:
    if p['product_id'] in pids: continue
    if p['product_page_url'] in urls: raise SystemExit('duplicate product URL: '+p['product_page_url'])
    add.append(p)
if add: append(P,add)
addd=[d for d in dists if d['distribution_id'] not in dids]
if addd: append(D,addd)

reg=json.loads(B.read_text(encoding='utf-8')); reg['reviewed_at']=today
p0=next(t for t in reg['tiers'] if t['priority_tier']=='P0')
if 'DR0118' not in p0['resource_ids']: p0['resource_ids'].append('DR0118')
B.write_text(json.dumps(reg,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

_,rs2=read(R); _,ps2=read(P); _,ds2=read(D)
assert len({x['resource_id'] for x in rs2})==len(rs2)
assert len({x['product_id'] for x in ps2})==len(ps2)
assert len({x['distribution_id'] for x in ds2})==len(ds2)
RIDS={x['resource_id'] for x in rs2}; PIDS={x['product_id'] for x in ps2}
assert all(x['resource_id'] in RIDS for x in ps2)
assert all(x['product_id'] in PIDS for x in ds2)
assert all(f'DP{i:06d}' in PIDS for i in range(522,528))
DIDS={x['distribution_id'] for x in ds2}; assert all(f'DD{i:06d}' in DIDS for i in range(543,549))
print(f'Read-back counts: {len(rs2)} resources | {len(ps2)} products | {len(ds2)} distributions')
